};

// Return original input WITH config values added at top level
return [{
  json: {
    ...input,  // Preserve all WhatsApp message data
    ...config  // Add config values at top level
  }
}];

// ===== ERROR HANDLING & INPUT VALIDATION =====
try {
  // Validate input
  const input = $input.first();
  if (!input || !input.json) {
    console.error('[Extraer Datos WhatsApp] Input vacío o inválido');
    return [{
      json: {
        error: true,
        error_message: 'Input inválido',
        error_node: 'Extraer Datos WhatsApp',
        phone_number: 'unknown'
      }
    }];
  }

  // Original code starts here
  // Obtener el input
const data = input.json;

// FILTRAR: Solo procesar si es un mensaje entrante
if (!data.messages || data.messages.length === 0) {
  console.log('⏭️ [Extraer Datos] Ignorando notificación de estado:', data.statuses?.[0]?.status);
  return [];
}

const message = data.messages[0];
const phoneNumber = message.from;
const userName = data.contacts[0].profile.name;
const messageId = message.id;
const timestamp = message.timestamp;

// ✅ MEJORA: DETECTAR Y PROCESAR CONTACTOS DE WHATSAPP
if (message.type === 'contacts') {
  console.log('📞 [Extraer Datos] Contacto de WhatsApp detectado');

  // Extraer información del contacto
  const contacts = message.contacts || [];
  if (contacts.length > 0) {
    const contact = contacts[0];
    const contactName = contact.name?.formatted_name || contact.name?.first_name || 'Sin nombre';
    const phones = contact.phones || [];

    if (phones.length > 0) {
      const contactPhone = phones[0].phone || phones[0].wa_id || 'Sin teléfono';
      const messageText = `Contacto: ${contactName} - Teléfono: ${contactPhone}`;

      console.log('✅ [Extraer Datos] Contacto extraído:', messageText);

      return [{
        json: {
          phone_number: phoneNumber,
          message: messageText,
          user_name: userName,
          message_id: messageId,
          timestamp: timestamp,
          is_unsupported_file: false,
          is_contact: true,
          contact_data: {
            name: contactName,
            phone: contactPhone,
            raw_contact: contact
          },
          raw_data: input
        }
      }];
    }
  }

  // Si no se pudo extraer el contacto, notificar
  console.log('⚠️ [Extraer Datos] No se pudo extraer información del contacto');
  return [{
    json: {
      phone_number: phoneNumber,
      message: 'Não consegui ler o contato. Por favor, envie o telefone do fornecedor como texto.',
      user_name: userName,
      message_id: messageId,
      timestamp: timestamp,
      is_unsupported_file: true,
      file_type: 'contacts',
      output: 'Não consegui ler o contato. Por favor, envie o telefone do fornecedor como texto.'
    }
  }];
}

// 📎 DETECTAR ARCHIVOS NO SOPORTADOS
if (message.type !== 'text') {
  console.log(`📎 [Extraer Datos] Archivo no soportado detectado: ${message.type}`);

  const unsupportedMessage = `📎 Oi! Percebi que você enviou um arquivo (${message.type}).

Por enquanto, só consigo processar mensagens de texto e contatos. 📝

🔜 Em breve vou poder receber fotos de notas fiscais!

Digite "menu" para ver as opções disponíveis.`;

  return [{
    json: {
      phone_number: phoneNumber,
      message: unsupportedMessage,
      user_name: userName,
      message_id: messageId,
      timestamp: timestamp,
      is_unsupported_file: true,
      file_type: message.type,
      output: unsupportedMessage
    }
  }];
}

// Extraer datos del mensaje de texto
const messageText = message.text.body;

console.log('📱 [Extraer Datos] Mensaje recibido de:', phoneNumber);
console.log('💬 [Extraer Datos] Contenido:', messageText);

return [{
  json: {
    phone_number: phoneNumber,
    message: messageText,
    user_name: userName,
    message_id: messageId,
    timestamp: timestamp,
    is_unsupported_file: false,
    raw_data: input
  }
}];

} catch (error) {
  console.error(`[Extraer Datos WhatsApp] Error: ${error.message}`);
  console.error(`[Extraer Datos WhatsApp] Stack: ${error.stack}`);

  return [{
    json: {
      error: true,
      error_message: error.message,
      error_node: 'Extraer Datos WhatsApp',
      phone_number: input?.json?.phone_number || input?.json?.user_data?.phone_number || 'unknown',
      output: 'Desculpe, algo deu errado. Por favor, tente novamente ou digite "menu" para voltar.'
    }
  }];
}
